import{_ as o,o as t,c as a,a2 as i}from"./chunks/framework.BKjcr3i4.js";const h=JSON.parse('{"title":"Ast","description":"","frontmatter":{"title":"Ast","audience":"internal","status":"draft","owner":"core-team"},"headers":[],"relativePath":"architecture/ast.md","filePath":"architecture/ast.md"}'),n={name:"architecture/ast.md"};function l(r,e,s,d,p,c){return t(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="omniui-ast-specification-mvp-v1" tabindex="-1">OmniUI AST Specification (MVP v1) <a class="header-anchor" href="#omniui-ast-specification-mvp-v1" aria-label="Permalink to &quot;OmniUI AST Specification (MVP v1)&quot;">​</a></h1><p>This document defines the <strong>Abstract Syntax Tree (AST)</strong> used by OmniUI.<br> The AST is designed to support:</p><ul><li>Rendering <strong>wireframes (SVG / Preview)</strong></li><li>Generating <strong>Figma structures</strong></li><li>Adapting to <strong>Design Systems</strong> (Fluent, Material, etc.)</li></ul><p>The model intentionally stays <strong>small and stable (11 nodes)</strong> so the parser and renderers remain simple.</p><p>Authoring-layer note:</p><ul><li>directives such as <code>% DataGroup ...</code> are intentionally outside this AST</li><li>they are expected to expand before AST emission</li><li>they are implemented in parser expansion and do not persist as AST nodes</li></ul><hr><h1 id="node-overview" tabindex="-1">Node Overview <a class="header-anchor" href="#node-overview" aria-label="Permalink to &quot;Node Overview&quot;">​</a></h1><p>All nodes share these base properties:</p><p>id: string<br> type: string<br> loc: {<br> startLine: number<br> startCol: number<br> endLine: number<br> endCol: number<br> }<br> children?: Node[]</p><p>The <code>loc</code> property enables:</p><ul><li>editor highlighting</li><li>preview ↔ editor synchronization</li><li>outline navigation</li></ul><p>Component content note:</p><ul><li>component nodes keep the raw <code>label</code> string and parsed inline markdown segments</li><li>this preserves formatting inside <code>[content](Component.tokens)</code> for bold, italic, strikethrough, highlight, inline code, links, images, emoji, and explicit line breaks</li></ul><hr><h1 id="_1-document" tabindex="-1">1. Document <a class="header-anchor" href="#_1-document" aria-label="Permalink to &quot;1. Document&quot;">​</a></h1><p>Root node representing a single screen.</p><p>Document { meta?: { layout?: string canvas?: string } regions: Region[] }</p><p>Example metadata (optional):</p><p>~ Layout: header-aside-main-footer<br> ~ Canvas: desktop-1440x1024</p><hr><h1 id="_2-region" tabindex="-1">2. Region <a class="header-anchor" href="#_2-region" aria-label="Permalink to &quot;2. Region&quot;">​</a></h1><p>Declared using:</p><p>~ Header<br> ~ Main<br> ~ Aside<br> ~ Footer<br> ~ Left<br> ~ Right</p><p>Case-insensitive.</p><p>Region { name: string body: Block[] }</p><hr><h1 id="_3-semanticblock" tabindex="-1">3. SemanticBlock <a class="header-anchor" href="#_3-semanticblock" aria-label="Permalink to &quot;3. SemanticBlock&quot;">​</a></h1><p>Optional semantic modes inside a region.</p><p>~ Form<br> ~ Navigation<br> ~ States</p><p>SemanticBlock { kind: &quot;Form&quot; | &quot;Navigation&quot; | &quot;States&quot; body: Block[] }</p><p>Notes:</p><ul><li><code>Navigation</code> can also be inferred heuristically when lists appear inside <code>Aside</code>.</li><li>Explicit declaration overrides heuristics.</li></ul><hr><h1 id="_4-markdownblock" tabindex="-1">4. MarkdownBlock <a class="header-anchor" href="#_4-markdownblock" aria-label="Permalink to &quot;4. MarkdownBlock&quot;">​</a></h1><p>Represents regular Markdown content.</p><p>MarkdownBlock { markdown: string }</p><p>Examples:</p><ul><li>paragraphs</li><li>lists</li><li>headings</li><li>strikethrough and highlight spans</li><li>inline code and fenced code blocks</li><li>images</li><li>standard markdown tables (data tables)</li></ul><hr><h1 id="_5-layouttable" tabindex="-1">5. LayoutTable <a class="header-anchor" href="#_5-layouttable" aria-label="Permalink to &quot;5. LayoutTable&quot;">​</a></h1><p>Markdown tables interpreted as <strong>layout containers</strong> rather than data tables.</p><p>Rules:</p><ul><li>Tables inside regions are candidates for layout tables.</li><li>Header rows with only empty cells are ignored.</li><li>Separator rows define alignment when present.</li><li>Alignment is inferred when missing.</li></ul><p>LayoutTable { columns: ColumnSpec[] rows: TableRow[] }</p><hr><h1 id="_6-columnspec" tabindex="-1">6. ColumnSpec <a class="header-anchor" href="#_6-columnspec" aria-label="Permalink to &quot;6. ColumnSpec&quot;">​</a></h1><p>Defines alignment for each column.</p><p>ColumnSpec { align: &quot;left&quot; | &quot;center&quot; | &quot;right&quot; }</p><p>Alignment rules:</p><p>If explicit separators exist:</p><p>|:--|:--😐--😐</p><p>Use them.</p><p>If not:</p><p>2 columns → left / right<br> 3 columns → left / center / right<br> 4+ columns → all left except last right</p><hr><h1 id="_7-tablerow" tabindex="-1">7. TableRow <a class="header-anchor" href="#_7-tablerow" aria-label="Permalink to &quot;7. TableRow&quot;">​</a></h1><p>TableRow { cells: TableCell[] }</p><p>Rows with no content are ignored by the renderer but still parsed.</p><hr><h1 id="_8-tablecell" tabindex="-1">8. TableCell <a class="header-anchor" href="#_8-tablecell" aria-label="Permalink to &quot;8. TableCell&quot;">​</a></h1><p>Cells may contain UI elements or markdown.</p><p>TableCell { align?: &quot;left&quot; | &quot;center&quot; | &quot;right&quot; body: Block[] }</p><p>Content inside a cell flows horizontally by default.</p><p>Notes:</p><ul><li>column alignment may come from the separator row</li><li>a cell may override that with inline alignment shortcuts such as <code>: value :</code> or <code>value :</code></li></ul><hr><h1 id="_9-button" tabindex="-1">9. Button <a class="header-anchor" href="#_9-button" aria-label="Permalink to &quot;9. Button&quot;">​</a></h1><p>Generated from syntax:</p><p><a href="#primary-sm-disabled">[Label]</a></p><p>Button { label: string variant: &quot;primary&quot; | &quot;secondary&quot; | &quot;danger&quot; | &quot;ghost&quot; size: &quot;sm&quot; | &quot;md&quot; | &quot;lg&quot; flags: { disabled?: boolean loading?: boolean full?: boolean } icon?: IconToken[] }</p><p>Example:</p><p><a href="#primary">[Sign in]</a><br><a href="#danger-md-disabled">[Delete]</a></p><hr><h1 id="_10-field" tabindex="-1">10. Field <a class="header-anchor" href="#_10-field" aria-label="Permalink to &quot;10. Field&quot;">​</a></h1><p>Unified representation for inputs, selects, checkboxes, radios, etc.</p><p>Example syntax:</p><ul><li><a href="#input-email" title="you@company.com">Email *</a></li></ul><p>Field { label: string required?: boolean disabled?: boolean sizing?: &quot;hug&quot; | &quot;fill&quot; icon?: IconToken control: Control }</p><p>Control variants:</p><p>Control = | { kind: &quot;input&quot; inputType: &quot;text&quot; | &quot;email&quot; | &quot;password&quot; | &quot;search&quot; | &quot;number&quot; size: &quot;sm&quot; | &quot;md&quot; | &quot;lg&quot; placeholder?: string } | { kind: &quot;textarea&quot; size: &quot;sm&quot; | &quot;md&quot; | &quot;lg&quot; placeholder?: string } | { kind: &quot;select&quot; size: &quot;sm&quot; | &quot;md&quot; | &quot;lg&quot; mode?: &quot;dropdown&quot; | &quot;list&quot; value?: string options?: string[] } | { kind: &quot;checkbox&quot; checked?: boolean } | { kind: &quot;radio&quot; selected?: boolean group?: string } | { kind: &quot;toggle&quot; on?: boolean }</p><p>Authoring note:</p><ul><li>markdown checkbox rows like <code>[x] Checked option</code> normalize to checkbox controls in the parsed model</li><li>parenthesized rows like <code>(x) Checked option</code> and <code>(o) Selected option</code> normalize to checkbox/radio controls in the parsed model</li><li><code>( )</code> inherits its control type from the contiguous block: checkbox when the block contains any <code>(x)</code>, otherwise radio</li><li><code>!!</code> bypasses heuristic expansion and produces plain <code>TextNode</code> content</li></ul><hr><h1 id="_11-icontoken" tabindex="-1">11. IconToken <a class="header-anchor" href="#_11-icontoken" aria-label="Permalink to &quot;11. IconToken&quot;">​</a></h1><p>Represents icon usage in UI elements.</p><p>IconToken { source: &quot;emoji&quot; | &quot;ds&quot; value: string }</p><hr><h1 id="_12-logo" tabindex="-1">12. Logo <a class="header-anchor" href="#_12-logo" aria-label="Permalink to &quot;12. Logo&quot;">​</a></h1><p>Generated from syntax:</p><p><a href="#logo-sm">[Brand]</a></p><p>Logo { text: string size: &quot;sm&quot; | &quot;md&quot; | &quot;lg&quot; }</p><p>Examples:</p><p><code>mail as IconComponent</code><br><code>lock as IconComponent</code><br><code>home as IconComponent</code></p><p>Adapters may map emojis to design system icons.</p><hr><h1 id="block-union-type" tabindex="-1">Block Union Type <a class="header-anchor" href="#block-union-type" aria-label="Permalink to &quot;Block Union Type&quot;">​</a></h1><p>Blocks used inside regions and cells.</p><p>Block = | MarkdownBlock | SemanticBlock | LayoutTable | Button | Field</p><hr><h1 id="example-ast" tabindex="-1">Example AST <a class="header-anchor" href="#example-ast" aria-label="Permalink to &quot;Example AST&quot;">​</a></h1><p>Input:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~ Header</span></span>
<span class="line"><span>| | | |</span></span>
<span class="line"><span>|---|---|---|</span></span>
<span class="line"><span>| list-icon Gmail | search action button | settings-icon user-icon |</span></span></code></pre></div><p>AST:</p><p>Document └ Region(Header) └ LayoutTable └ Row ├ Cell(left) │ └ MarkdownBlock(&quot;list-icon Gmail&quot;) ├ Cell(center) │ └ Field(kind=input, type=search) └ Cell(right) └ MarkdownBlock(&quot;settings-icon user-icon&quot;)</p><hr><h1 id="design-goals" tabindex="-1">Design Goals <a class="header-anchor" href="#design-goals" aria-label="Permalink to &quot;Design Goals&quot;">​</a></h1><p>The AST is intentionally minimal to ensure:</p><ul><li>deterministic parsing</li><li>simple rendering to SVG</li><li>easy mapping to Figma</li><li>adapter compatibility with multiple design systems</li></ul><p>Future extensions should add <strong>new nodes without breaking existing ones</strong>.</p>`,110)])])}const m=o(n,[["render",l]]);export{h as __pageData,m as default};
